@startuml

class Customer {
  + VATNumber : string
  + Name : string
  + PhoneNumber : string
  + Address : string
}

class DeliveryCenter {
  + Name : string
  + Address : string
}

class Package {
  + IdentifierCode : string
  + Weight : float
  + IsUrgent : boolean
}

class Courier {
  + VATNumber : string
  + Name : string
  + PhoneNumber : string
}

Customer "1" -- "0..*" Package : sends
Customer "1" -- "0..*" Package : receives
Customer "1" -- "0..1" DeliveryCenter : associated to
DeliveryCenter "1" -- "0..*" Package : routes through
DeliveryCenter "1" -- "0..*" Courier : employs
Courier "1" -- "0..*" Package : assigned to

@enduml

